CREATE OR REPLACE FUNCTION public.ikigai_kanji_bomb_verified(p_lesson integer,p_attempt uuid,p_answers jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u uuid:=ikigai_rewards_private.member(); n int;c int;expected int;r jsonb;
BEGIN
 IF p_lesson IS NULL OR p_lesson NOT BETWEEN 1 AND 32 OR p_attempt IS NULL OR jsonb_typeof(p_answers) IS DISTINCT FROM 'array' OR pg_column_size(p_answers)>50000 THEN RAISE EXCEPTION 'Invalid Kanji answer list';END IF;
 SELECT count(*) INTO expected FROM ikigai_rewards_private.kanji_verified_keys WHERE lesson=p_lesson;
 IF expected=0 OR jsonb_array_length(p_answers)<>expected THEN RAISE EXCEPTION 'Incomplete Kanji lesson';END IF;
 SELECT count(distinct a.id),count(*) filter(where a.reading=k.reading AND a.meaning=k.meaning) INTO n,c
 FROM jsonb_to_recordset(p_answers) a(id text,reading text,meaning text) JOIN ikigai_rewards_private.kanji_verified_keys k ON k.id=a.id AND k.lesson=p_lesson;
 IF n<>expected THEN RAISE EXCEPTION 'Invalid Kanji question IDs';END IF;
 r:=ikigai_rewards_private.settle_v2(u,'kanji_bomb','kanji-bomb:'||p_lesson,p_attempt,c,expected,least(c*10,200),50);
 RETURN r||jsonb_build_object('xp',r->'xp_total','coins',r->'coins_total','correct',(select correct from ikigai_rewards_private.policy_attempts where user_id=u and source='kanji_bomb' and attempt=p_attempt),'total',expected);
END$$;
REVOKE ALL ON FUNCTION public.ikigai_kanji_bomb_verified(integer,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ikigai_kanji_bomb_verified(integer,uuid,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION ikigai_rewards_private.verify_grammar_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE n int;c int;matched int;unique_ids int;
BEGIN
 IF NEW.user_id IS DISTINCT FROM auth.uid() OR NEW.attempt_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.ikigai_world_profiles p JOIN auth.users u ON u.id=p.user_id WHERE p.user_id=NEW.user_id AND p.role='student' AND NOT coalesce(u.is_anonymous,false)) THEN RAISE insufficient_privilege;END IF;
 IF jsonb_typeof(NEW.question_ids) IS DISTINCT FROM 'array' OR jsonb_typeof(NEW.answers) IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.question_ids)<>jsonb_array_length(NEW.answers) OR jsonb_array_length(NEW.answers)>500 THEN RAISE EXCEPTION 'Invalid grammar answer list';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.answers) a WHERE a not in ('"A"'::jsonb,'"B"'::jsonb,'"C"'::jsonb,'"D"'::jsonb,'null'::jsonb)) THEN RAISE EXCEPTION 'Invalid answer';END IF;
 WITH effective AS (
 SELECT coalesce(e.question_id,k.id) id,case when e.question_id is not null then e.payload->>'correct' else k.answer end answer
 FROM (SELECT * FROM ikigai_rewards_private.grammar_verified_keys WHERE test_id=NEW.test_id) k
 FULL JOIN (SELECT * FROM public.ikigai_grammar_question_edits WHERE test_id=NEW.test_id) e ON e.question_id=k.id
 ), graded AS (SELECT * FROM effective WHERE answer IN ('A','B','C','D')),
 submitted AS (SELECT x.id,NEW.answers->>(x.i::int-1) answer FROM jsonb_array_elements_text(NEW.question_ids) WITH ORDINALITY x(id,i))
 SELECT (SELECT count(*) FROM graded),count(g.id),count(distinct s.id),count(*) filter(where s.answer=g.answer) INTO n,matched,unique_ids,c FROM submitted s LEFT JOIN graded g ON g.id=s.id;
 IF n=0 OR matched<>n OR unique_ids<>n OR jsonb_array_length(NEW.question_ids)<>n THEN RAISE EXCEPTION 'Question bank changed or incomplete. Reload exam.';END IF;
 NEW.correct_count:=c;NEW.total_count:=n;NEW.score_percent:=round(c*100.0/n);NEW.created_at:=now();RETURN NEW;
END$$;
REVOKE ALL ON FUNCTION ikigai_rewards_private.verify_grammar_insert() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS ikigai_verify_grammar_before_insert ON public.ikigai_grammar_results;
CREATE TRIGGER ikigai_verify_grammar_before_insert BEFORE INSERT ON public.ikigai_grammar_results FOR EACH ROW EXECUTE FUNCTION ikigai_rewards_private.verify_grammar_insert();
NOTIFY pgrst,'reload schema';